// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes32 role, address account) public {
        // No setup grants `role` to `account`: role is an arbitrary fuzzed bytes32 and
        // account is an arbitrary fuzzed address, distinct from the deployer/admin
        // (which only holds TIMELOCK_ADMIN_ROLE, never the fuzzed role).
        // Admissible domain: entire input space (kept maximally wide).

        // General rule: for any role/account pair with no granted membership,
        // the public hasRole view must report false.
        assertTrue(!c.hasRole(role, account));
    }
}
